        const xgSeed = 320;
        const data = new Uint8Array(20);
        data.set(md5Bytes(toBytes(query)).subarray(0, 4), 0);
        if (bodyJson) data.set(md5Bytes(toBytes(bodyJson)).subarray(0, 4), 4);
        const mssdk = 67503104;
        data[12] = mssdk & 0xff; data[13] = (mssdk >> 8) & 0xff; data[14] = (mssdk >> 16) & 0xff; data[15] = (mssdk >> 24) & 0xff;
        data[16] = (khronos >>> 24) & 0xff; data[17] = (khronos >>> 16) & 0xff; data[18] = (khronos >>> 8) & 0xff; data[19] = khronos & 0xff;
