        ret[0] = GORGON_84[4]; ret[1] = GORGON_84[5];
        ret[2] = xgRand & 0xff; ret[3] = (xgRand >> 8) & 0xff;
        ret[4] = xgSeed & 0xff; ret[5] = (xgSeed >> 8) & 0xff;
        ret.set(out, 6);
        return toHex(ret);
