// 面板一行「key|行名|id:名,…」→ {key, name, value:[{n,v}]}；行名「全部主題」去掉「全部」當名，"" = 全部（第一項）
function snapshotPanel(rows) {
    return rows.map((row) => {
        const parts = row.split('|');
        const rowName = parts[1] || '';
        const name = rowName.startsWith('全部') && rowName.length > 2 ? rowName.slice(2) : rowName;
        const value = [{n: '全部', v: ''}];
        parts.slice(2).join('|').split(',').forEach((item) => {
            const i = item.indexOf(':');
            if (i > 0) value.push({v: item.slice(0, i), n: item.slice(i + 1)});
        });
        return {key: parts[0], name, value};
    });
}

export default class Hongguo extends Spider {
    
    base = DEFAULT_BASE;
    // scene(default/short_play/comic_series/ai_series) → 篩選面板 [{key,name,value:[{n,v}]}]
    panels = {};
    cacheSiteKey = '';
    device = null;
    generation = 0;
    // 頻道推薦流：第 1 頁取頻道首屏，之後用 cell/change 按 next_offset 續頁；按頻道分別記狀態
    feeds = new Map();
    quality = '';
    findCursors = new Map();
    searchCursors = new Map();

    async init(extend = '') {
        const options = (extend.trim().startsWith('{') ? safeJson(extend) : null) || {};
        this.base = normalizeBase(options.base_url || options.host || DEFAULT_BASE);
        // 用站點 key 隔離快取的設備身分；未提供時使用固定默認值。
        this.cacheSiteKey = text(this.siteKey || options.site_key || options.siteKey) || 'hongguo';
        this.quality = text(options.quality); // 想要的清晰度，如 "720"；留空取最高可解碼檔
        this.clearPages();
        CLASS_SCENES.forEach((scene, i) => { this.panels[scene] = snapshotPanel(PANEL_SNAPSHOT[i]); });
        this.device = this.normalizeDevice(options) || this.normalizeDevice(this.local.get(this.scope())) || BUILTIN_DEVICE;
        this.generation++;
    }

    scope() {
        return 'hongguo:' + (this.cacheSiteKey || 'default');
    }

    normalizeDevice(d) {
        if (!object(d)) return null;
        const device_id = text(d.device_id),
            install_id = text(d.install_id);
        return /^\d{6,}$/.test(device_id) && /^\d{6,}$/.test(install_id) ? {
            device_id,
            install_id,
            cdid: text(d.cdid)
        } : null;
    }
    // 用目前設備執行 App 請求；失敗疑似設備失效時，自動註冊新設備重試一次。
    async withDevice(call) {
        const version = this.generation;
        try {
            return await call(this.device);
        } catch (error) {
            if (version !== this.generation || error.code !== 'EMPTY_RESPONSE') throw error;
            let fresh;
            try {
                fresh = await registerDevice(this.net.req);
            } catch (regErr) {
                throw new Error(errorText(error) + '；設備更新失敗：' + errorText(regErr));
            }
            if (version !== this.generation) throw error;
            const result = await call(fresh);
            this.checkGeneration(version);
            this.local.set(this.scope(), fresh);
            this.device = fresh;
            return result;
        }
    }

    async homeContent(filter) {
        void filter;
        this.loadPanels();
        const classes = CLASS_IDS.map((id, i) => cls(id, CLASS_NAMES[i])).concat(cls('audiobook', '听书'));
        const filters = {};
        CLASS_IDS.forEach((id, i) => {
            // 體裁固定的分類（真人/漫/AI劇）不顯示「體裁」行；只有「找劇」能切體裁
            filters[id] = this.panel(CLASS_SCENES[i])
                .filter((f) => i === 0 || f.key !== 'genre')
                .map((f) => ({key: f.key, name: f.name, init: '', value: f.value}));
        });
        const result = {class: classes, filters};
        classes.forEach((item) => { if (filters[item.type_id]) item.filters = filters[item.type_id]; });
        return result;
    }

    panel(scene) {
        return this.panels[scene] || [];
    }

    async categoryContent(tid, pg, filter, extend) {
        void filter;
        const page = pageNumber(pg);
        const selected = object(extend) ? extend : {};
        const id = String(tid);
        if (id === 'audiobook') return this.audioCategory(page);
        const index = Math.max(CLASS_IDS.indexOf(id), 0);
        return this.filterCategory(index, page, selected);
    }

    async audioCategory(page) {
        const version = this.generation;
        if (page === 1) this.feeds.set(AUDIO_TAB, {cursors: new Map(), pagecount: 1});
        const feed = this.feeds.get(AUDIO_TAB);
        const cursor = feed?.cursors.get(page);
        const empty = {list: [], page, pagecount: feed?.pagecount || 1, limit: PAGE_SIZE, total: 0};
        if (page > 1 && !cursor) return empty;
        try {
            const result = page === 1 ? await this.loadAudioFeed() : await this.moreAudioFeed(feed.base, cursor);
            this.checkGeneration(version);
            if (this.feeds.get(AUDIO_TAB) !== feed || feed.cursors.get(page) !== cursor) {
                throw new Error('書單已更新，請重新載入');
            }
            if (page === 1) feed.base = result.base;
            const more = result.more && result.list.length > 0 && Number.isSafeInteger(result.offset) && result.offset > (cursor?.offset ?? 0);
            for (let nextPage = page + 1; nextPage <= feed.pagecount; nextPage++) feed.cursors.delete(nextPage);
            if (more) feed.cursors.set(page + 1, {offset: result.offset, session_id: result.session});
            feed.pagecount = more ? page + 1 : page;
            return {...empty, list: result.list, pagecount: feed.pagecount, limit: Math.max(result.list.length, 1)};
        } catch (error) {
            return {...empty, msg: '聽書載入失敗：' + errorText(error)};
        }
    }

    async loadAudioFeed() {
        const data = await this.withDevice((d) => bookmallTabs(this.net.req, d, AUDIO_TAB));
        const tab = array(data.tab_item).find((item) => Number(item?.tab_type) === AUDIO_TAB);
        if (!Array.isArray(tab?.cell_data)) throw new Error('紅果未提供聽書書單');
        const box = tab.cell_data.find((cell) => Number(cell?.show_type) === 337);
        const base = {
            cell_id: text(box?.cell_id_str || box?.cell_id),
            tab_type: AUDIO_TAB,
            show_type: text(box?.show_type),
            client_template: text(tab.client_template),
            version_tag: text(tab.version_tag)
        };
        const session = text(tab.session_id);
        // Tab 的 has_more 是頻道層級，推薦單元有獨立續頁。
        return {base, list: this.audioCards(tab.cell_data), offset: Number(tab.next_offset), session, more: !!(base.cell_id && session)};
    }

    async moreAudioFeed(base, cursor) {
        const data = await this.withDevice((d) => bookmallMore(this.net.req, d, {
            ...base, ...cursor, client_req_type: 2
        }));
        const more = data.has_more === true || data.has_more === 1;
        if (!object(data.cell_view) && more) throw new Error('續頁缺少聽書書單');
        return {
            list: this.audioCards([data.cell_view]),
            offset: Number(data.next_offset),
            session: text(data.session_id) || cursor.session_id,
            more
        };
    }

    audioCards(cells) {
        const books = new Map();
        const collect = (cell) => {
            for (const book of array(cell?.book_data)) {
                const id = text(book?.book_id);
                if (/^\d{6,}$/.test(id) && text(book.book_name) && !books.has(id)) books.set(id, this.audioCard(book, id));
            }
            array(cell?.cell_data).forEach(collect);
        };
        cells.forEach(collect);
        return Array.from(books.values());
    }

    async searchContent(key, quick, pg = '1') {
        void quick;
        const page = pageNumber(pg);
        const keyword = String(key || '').trim();
        const response = {list: [], page, pagecount: 1, limit: PAGE_SIZE, total: 0};
        if (!keyword) return response;
        const version = this.generation;
        try {
            const initial = {offset: 0, searchId: '', passback: ''};
            const {list, pagecount} = await this.cursorPage(this.searchCursors, keyword, page, initial,
                (cursor) => this.searchPage(keyword, cursor, version));
            this.checkGeneration(version);
            const found = await this.searchSeries(keyword, list, version);
            this.checkGeneration(version);
            return {...response, pagecount, ...found};
        } catch (error) {
            return {...response, pagecount: page, msg: errorText(error)};
        }
    }

    // 上游去重後每頁筆數會變動，跳頁須沿用前頁回傳的游標。
    async cursorPage(states, key, page, initial, load) {
        const version = this.generation;
        let cursors = states.get(key);
        if (!cursors || page === 1) {
            if (!cursors && states.size >= 8) states.delete(states.keys().next().value);
            cursors = [initial];
            states.set(key, cursors);
        }
        let index = Math.min(page - 1, cursors.length - 1);
        let cursor = cursors[index];
        while (cursor) {
            const {list, next} = await load(cursor);
            this.checkGeneration(version);
            if (states.get(key) !== cursors || cursors[index] !== cursor) {
                throw new Error('清單已更新，請重新載入');
            }
            index++;
            cursors.length = index;
            cursors.push(next);
            if (index === page) return {list, pagecount: next ? page + 1 : page};
            cursor = next;
        }
        return {list: [], pagecount: index};
    }

    async detailContent(ids) {
        const responses = await this.net.map(ids, this.detailItem);
        const failed = responses.find(response => !response.list.length && response.msg);
        if (failed) return failed;
        return {...responses[0], list: responses.flatMap(response => response.list)};
    }

    async detailItem(id) {
        const audio = /^audio:(\d{6,})$/.exec(text(id));
        if (audio) return this.audioItem(audio[1]);
        const seriesId = seriesIdOf(id);
        if (!seriesId) return {
            list: [],
            msg: '無效的劇集 ID'
        };
        try {
            const webKey = this.webDetailKey(seriesId);
            this.refreshWebDetail(seriesId);
            const vd = await this.withDevice((d) => videoDetail(this.net.req, d, seriesId));
            const web = this.net.peek(webKey) || {};
            const eps = array(vd.video_list).filter((v) => v && v.vid);
            if (!eps.length) throw new Error('沒有分集');
            const title = text(vd.series_title || web.series_name) || '紅果短劇';
            const episodes = eps.map((v, index) => safeLabel(this.episodeLabel(v, index)) + '$' + String(v.vid));
            const social = web.social || {};
            const hot = text(social.hot_score_data && social.hot_score_data.text) || array(vd.series_sub_title_list).map(text).filter((item) => item && !/^全\d+集$/.test(item)).join(' · ');
            const remarks = [text(vd.episode_right_text || web.episode_right_text), social.rating ? '評分' + social.rating : '', hot].filter(Boolean).join(' · ');
            return {
                list: [{
                    vod_id: seriesId,
                    vod_name: title,
                    vod_pic: this.picture(web.series_cover || vd.series_cover),
                    type_name: this.detailTags(vd, web).map(text).filter(Boolean).join(' / '),
                    vod_remarks: remarks,
                    vod_actor: array(web.celebrities).map((item) => text(item && item.nickname)).filter(Boolean).join(' / '),
                    vod_content: text(vd.series_intro || web.series_intro),
                    vod_play_from: '紅果',
                    vod_play_url: episodes.join('#')
                }]
            };
        } catch (error) {
            return {
                list: [],
                msg: '詳情載入失敗：' + errorText(error)
            };
        }
    }

    audioCard(book, id) {
        return {
            vod_id: 'audio:' + id,
            vod_name: text(book.book_name),
            vod_pic: this.picture(book.audio_thumb_url_hd || book.thumb_url),
            vod_remarks: text(book.author),
            style: {type: 'rect', ratio: 1}
        };
    }

    async audioItem(bookId) {
        const version = this.generation;
        try {
            const [book, chapters] = await Promise.all([
                this.audioBook(bookId),
                audioDirectory(this.net.req, bookId)
            ]);
            this.checkGeneration(version);
            const tone = text(book.tones).split(',')[0];
            const toneId = /^\d+$/.test(tone) ? tone : (Number(book.genre_type) === 1 ? '0' : '1');
            const episodes = [];
            // isChapterLock 只限制網頁試讀。音訊權限由紅果取址接口判斷。
            chapters.forEach((chapter, index) => {
                const itemId = text(chapter?.itemId);
                if (!/^\d{6,}$/.test(itemId) || Number(chapter.needPay) > 0) return;
                const label = safeLabel(text(chapter.title) || '第' + (index + 1) + '章');
                episodes.push(label + '$audio:' + bookId + ':' + itemId + ':' + toneId);
            });
            if (!episodes.length) throw new Error('沒有可播放的章節');
            return {
                list: [{
                    ...this.audioCard(book, bookId),
                    vod_remarks: '共 ' + episodes.length + ' 章',
                    vod_actor: text(book.author),
                    vod_content: text(book.book_abstract_v2 || book.abstract),
                    vod_play_from: '聽書',
                    vod_play_url: episodes.join('#')
                }]
            };
        } catch (error) {
            return {list: [], msg: '書籍詳情載入失敗：' + errorText(error)};
        }
    }

    detailTags(vd, web) {
        if (array(web.tags).length) return web.tags;
        const tags = array(vd.secondary_infos).filter((item) => item && item.data_type === 3).map((item) => item.content);
        return tags.length ? tags : array(safeJson(vd.category_schema)).map((item) => item && item.name);
    }

    async playerContent(flag, id) {
        const vid = text(id);
        const audio = AUDIO_EPISODE.exec(vid);
        if (!audio && !/^\d{6,}$/.test(vid)) return {
            parse: 0,
            jx: 0,
            msg: '無效的播放參數'
        };
        const version = this.generation;
        try {
            if (audio) {
                const [, bookId, itemId, toneId] = audio;
                const timing = this.audioTiming(bookId, itemId, toneId).catch(() => null);
                const artwork = this.audioArtwork(bookId).catch(() => '');
                const stream = await this.withDevice((device) => audioStream(this.net.req, device, bookId, itemId, toneId));
                const [points, cover] = await Promise.all([timing, artwork]);
                this.checkGeneration(version);
                const result = playbackResult(stream, 'audio/mp4');
                if (cover) result.artwork = cover;
                if (stream.vid && points?.vid === stream.vid && array(points.time_points).length) {
                    result.subs = [{name: '同步字幕', lang: 'zh-CN', format: 'text/vtt', flag: 1,
                        url: this.proxyUrl({subtitle: vid, vid: stream.vid})}];
                }
                return result;
            }
            const model = await this.withDevice((device) => videoModel(this.net.req, device, vid));
            this.checkGeneration(version);
            const quality = this.quality || flag;
            let stream = pickStream(model, quality);
            if (!stream) {
                const compatible = await compatibleModel(this.net.req, model);
                this.checkGeneration(version);
                if (compatible) stream = pickStream(compatible, quality);
            }
            if (!stream) throw new Error('紅果 App 未提供相容的播放來源');
            return playbackResult(stream, 'video/mp4');
        } catch (error) {
            return {
                parse: 0,
                jx: 0,
                msg: '播放地址取得失敗：' + errorText(error)
            };
        }
    }

    audioBookKey(bookId) {
        return ['hongguo:audio-detail', this.cacheOwner(), this.generation, bookId].join(':');
    }

    audioBook(bookId) {
        return this.net.cached(this.audioBookKey(bookId), {ttl: WEB_TTL, stale: false}, async () => {
            const book = await this.withDevice((d) => audioDetail(this.net.req, d, bookId));
            if (text(book?.book_id) !== bookId || !text(book.book_name)) throw new Error('缺少書籍資料');
            return book;
        });
    }

    async audioArtwork(bookId) {
        const req = (url, options) => this.net.req(url, {...options, timeout: 4000});
        const book = this.net.peek(this.audioBookKey(bookId)) || await audioDetail(req, this.device, bookId);
        if (text(book?.book_id) !== bookId) return '';
        const cover = text(book.audio_thumb_url_hd || book.thumb_url);
        const image = /^https?:\/\/(?:p\d+-reading-sign\.fqnovelpic\.com|p\d+-novel\.byteimg\.com)\/(?:origin\/)?((?:novel-static|novel-pic)\/[\da-f]{32})(?=~|[?#]|$)/i.exec(cover);
        return image ? this.picture(`https://p3-novel.byteimg.com/${image[1]}~tplv-blur:8.image`) : '';
    }

    audioTiming(bookId, itemId, toneId) {
        const device = this.device;
        const key = ['hongguo:timing', this.cacheOwner(), device.device_id, this.generation, bookId, itemId, toneId].join(':');
        const req = (url, options) => this.net.req(url, {...options, timeout: 4000});
        return this.net.cached(key, {ttl: WEB_TTL, stale: false}, () => audioTimepoints(req, device, bookId, itemId, toneId));
    }

    async proxy(params) {
        const audio = AUDIO_EPISODE.exec(text(params.subtitle));
        if (!audio || !/^[a-z0-9]{16,64}$/i.test(text(params.vid))) return [404, 'text/plain', 'Not found'];
        const [, bookId, itemId, toneId] = audio;
        const version = this.generation;
        try {
            const timing = await this.audioTiming(bookId, itemId, toneId);
            const points = array(timing?.time_points);
            if (timing?.vid !== params.vid || !points.length) return [404, 'text/plain', '沒有同步字幕'];
            this.checkGeneration(version);
            const html = points.some((point) => point?.position_info_v2 && !text(point.text))
                ? await this.subtitleChapter(bookId, itemId, toneId, version) : '';
            const vtt = await audioVtt(points, html);
            this.checkGeneration(version);
            return vtt ? [200, 'text/vtt; charset=utf-8', vtt] : [404, 'text/plain', '沒有同步字幕'];
        } catch (error) {
            return [502, 'text/plain; charset=utf-8', '字幕載入失敗：' + errorText(error)];
        }
    }

    async subtitleChapter(bookId, itemId, toneId, version) {
        const device = this.device;
        const key = ['hongguo:reader', this.cacheOwner(), device.device_id, version].join(':');
        const reader = await this.net.cached(key, {ttl: 600000, stale: false}, () => registerReaderKey(this.net.req, device));
        this.checkGeneration(version);
        return audioText(this.net.req, device, bookId, itemId, toneId, reader);
    }

    episodeLabel(v, index) {
        const title = text(v.episode_title || v.title || v.name);
        if (title && title.length <= 24) return title;
        const n = parseInt(v.vid_index, 10);
        return '第' + (Number.isFinite(n) && n > 0 ? n : index + 1) + '集';
    }

    action(action) {
        const seriesId = seriesIdOf(action);
        return seriesId ? {web: {url: this.base + '/detail?series_id=' + seriesId}} : {msg: '無效的操作'};
    }

    isVideoFormat(url) {
        return /^https?:\/\/[^\s]+\.(?:mp4|m3u8)(?:[?#]|$)/i.test(String(url || '')) || /mime_type=video_mp4/i.test(String(url || ''));
    }

    liveContent(url) {
        return [];
    }

    destroy() {
        this.generation++;
        this.clearPages();
    }

    clearPages() {
        this.feeds.clear();
        this.findCursors.clear();
        this.searchCursors.clear();
    }

    cacheOwner() {
        return __hgSign.md5Hex(JSON.stringify([this.base, 'guest', this.device.device_id, this.device.install_id]));
    }

    checkGeneration(version) {
        if (version !== this.generation) throw new Error('站點已重新載入，請重試');
    }

    loadPanels() {
        const version = this.generation;
        CLASS_SCENES.forEach((scene) => {
            const key = 'hongguo:panel:2:' + scene;
            const cached = this.net.peek(key);
            if (Array.isArray(cached) && cached.length) this.panels[scene] = cached;
            this.net.refresh(key, {ttl: PANEL_TTL, persist: true}, () => this.loadPanel(scene, version));
        });
    }

    async loadPanel(scene, version) {
        this.checkGeneration(version);
        const data = await landpagePanel(this.net.req, this.device, scene);
        this.checkGeneration(version);
        const rows = [];
        array(data.selector_rows).forEach((row) => {
            const type = text(row.type), rowName = text(row.row_name);
            if (!/^[a-z0-9_]+$/.test(type) || !rowName) return;
            const name = rowName.startsWith('全部') && rowName.length > 2 ? rowName.slice(2) : rowName;
            const value = [{n: '全部', v: ''}];
            array(row.items).forEach((item) => {
                const id = text(item.selector_item_id), label = text(item.show_name);
                if (id && label && !value.some((entry) => entry.v === id)) value.push({v: id, n: label});
            });
            if (value.length > 1) rows.push({key: type, name, value});
        });
        if (!rows.length) throw new Error('篩選資料為空');
        return rows;
    }

    // 頻道首屏：回傳續頁用的 feed 狀態與首屏卡片
    async loadFeed(tabType) {
        const version = this.generation;
        const data = await bookmallTabs(this.net.req, this.device, tabType);
        const tab = array(data.tab_item).find((t) => Number(t && t.tab_type) === tabType);
        const box = array(tab && tab.cell_data).find((c) => array(c && c.cell_data).some((x) => x && array(x.video_data).length));
        if (!box) throw new Error('推薦流為空');
        const feed = {
            version,
            base: {
                cell_id: text(box.cell_id_str || box.cell_id),
                tab_type: tabType,
                session_id: text(tab.session_id),
                client_template: text(tab.client_template),
                tab_version: text(tab.tab_version),
                version_tag: text(tab.version_tag),
                show_type: text(box.show_type)
            },
            offsets: new Map()
        };
        return {feed, list: this.feedCards(box.cell_data), next: Number(box.next_offset), more: true};
    }

    async moreFeed(feed, offset) {
        this.checkGeneration(feed.version);
        const data = await bookmallMore(this.net.req, this.device, Object.assign({}, feed.base, {offset, client_req_type: 2}));
        this.checkGeneration(feed.version);
        if (text(data.session_id)) feed.base.session_id = text(data.session_id);
        const view = data.cell_view || {};
        return {list: this.feedCards(view.cell_data), next: Number(data.next_offset), more: data.has_more === true || data.has_more === 1};
    }

    feedCards(cells) {
        return array(cells).map((c) => c && array(c.video_data)[0]).filter(Boolean).map((v) => this.toCard({
            series_id: v.series_id,
            series_name: v.title,
            series_cover: v.cover,
            episode_cnt: v.episode_cnt,
            episode_right_text: v.rec_text
        })).filter(Boolean);
    }

    async feedCategory(tabType, page) {
        const version = this.generation;
        let result, feed;
        if (page === 1) {
            result = await this.loadFeed(tabType);
            feed = result.feed;
        } else {
            feed = this.feeds.get(tabType);
            const offset = feed && feed.offsets.get(page);
            if (offset === undefined) throw new Error('推薦流需從第一頁開始');
            result = await this.moreFeed(feed, offset);
        }
        this.checkGeneration(version);
        if (page === 1) this.feeds.set(tabType, feed);
        const has = result.more && result.list.length > 0 && Number.isFinite(result.next) && result.next > 0;
        if (has) feed.offsets.set(page + 1, result.next);
        return {list: result.list, page, pagecount: has ? page + 1 : page, limit: Math.max(result.list.length, 1), total: 0};
    }

    categorySelection(scene, selected) {
        const panel = this.panel(scene);
        const genre = text(selected.genre);
        const genres = panel.find((row) => row.key === 'genre')?.value || [];
        const reqScene = scene === 'default' && CLASS_SCENES.includes(genre) && genres.some((option) => option.v === genre)
            ? genre : scene;
        const rows = this.panel(reqScene);
        const items = Object.fromEntries(rows.map((row) => [row.key, []]));
        if (reqScene !== 'default') items.genre = [reqScene];
        let filtered = reqScene !== scene;
        for (const row of panel) {
            if (row.key === 'genre') continue;
            const id = text(selected[row.key]);
            const option = id && row.value.find((value) => value.v === id);
            if (!option) continue;
            items[row.key] = [reqScene === scene ? id : this.genreOptionId(rows, row.key, option)];
            filtered = true;
        }
        return {reqScene, items, filtered};
    }

    genreOptionId(rows, key, option) {
        const values = rows.find((row) => row.key === key)?.value || [];
        if (values.some((value) => value.v === option.v)) return option.v;
        // 各體裁使用不同 ID。同名且唯一的選項才可沿用。
        const matches = values.filter((value) => value.v && value.n === option.n);
        if (matches.length === 1) return matches[0].v;
        throw new Error('所選體裁沒有「' + option.n + '」篩選');
    }

    // App「篩選」頁：每個篩選行進 select_items 同名數組（空數組=全部）；全為「全部」且有頻道時走個性化推薦流
    async filterCategory(classIndex, page, selected) {
        const name = CLASS_NAMES[classIndex];
        const response = {list: [], page, pagecount: page, limit: LANDPAGE_SIZE, total: 0};
        try {
            const scene = CLASS_SCENES[classIndex];
            const {reqScene, items, filtered} = this.categorySelection(scene, selected);
            const tab = FEED_TABS[CLASS_IDS[classIndex]];
            if (!filtered && tab !== undefined) return await this.feedCategory(tab, page);
            const key = CLASS_IDS[classIndex] + '|' + reqScene + '|' + JSON.stringify(items);
            const result = await this.cursorPage(this.findCursors, key, page, {offset: 0, session: ''},
                (cursor) => this.filterPage(reqScene, items, cursor));
            return {...response, ...result};
        } catch (error) {
            return {...response, msg: name + '載入失敗：' + errorText(error)};
        }
    }

    async filterPage(scene, items, cursor) {
        const data = await landpageContent(this.net.req, this.device, scene, items, cursor.offset, LANDPAGE_SIZE, cursor.session);
        const list = array(data.video_data).map((video) => this.landpageCard(video)).filter(Boolean);
        const offset = Number(data.next_offset);
        const more = (data.has_more === true || data.has_more === 1) && Number.isFinite(offset) && offset > cursor.offset;
        return {list, next: more ? {offset, session: text(data.session_id) || cursor.session} : null};
    }

    // landpage 卡片：集數→vod_remarks，熱度(sub_title_list)→vod_year
    landpageCard(v) {
        if (!object(v)) return null;
        const seriesId = text(v.series_id);
        if (!/^\d+$/.test(seriesId)) return null;
        const hot = array(v.sub_title_list).map((x) => text(x && x.content)).filter(Boolean).join(' · ');
        const eps = v.episode_cnt && String(v.episode_cnt) !== '0' ? '全' + v.episode_cnt + '集' : '';
        const card = {
            vod_id: seriesId,
            vod_name: text(v.title) || '紅果短劇',
            vod_pic: this.picture(v.cover),
            vod_remarks: eps || hot,
            style: {type: 'rect', ratio: 0.75}
        };
        if (hot && eps) card.vod_year = hot;
        return card;
    }

    async getHtml(url) {
        const response = await this.net.req(url, {
            method: 'GET',
            timeout: 30000,
            redirect: 1,
            headers: {
                'User-Agent': UA,
                Accept: 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
                'Accept-Language': 'zh-CN,zh;q=0.9',
                Referer: this.base + '/'
            }
        });
        if (response && response.error) throw new Error('網路請求失敗：' + response.error);
        const code = Number(response && response.code) || 0;
        if (!code || code < 200 || code >= 300) throw new Error(code ? 'HTTP ' + code : '網路請求失敗');
        const html = String(response && response.content || '');
        if (!html) throw new Error('頁面內容為空');
        return html;
    }

    webDetailKey(seriesId) {
        return 'hongguo:detail:' + this.base + '/detail?series_id=' + seriesId;
    }

    refreshWebDetail(seriesId) {
        const version = this.generation;
        const url = this.base + '/detail?series_id=' + seriesId;
        this.net.refresh(this.webDetailKey(seriesId), {ttl: WEB_TTL}, async () => {
            this.checkGeneration(version);
            const data = routerData(await this.getHtml(url));
            this.checkGeneration(version);
            const section = findSection(data, 'seriesDetail') || {};
            const web = object(section.seriesDetail) ? section.seriesDetail : {};
            web.social = object(section.seriesSocialInfo) ? section.seriesSocialInfo : {};
            return web;
        });
    }

    matchesSeries(keyword, title) {
        const match = /^(.+?)第[\d一二三四五六七八九十百零〇两兩]+[季部篇]$/.exec(title);
        return !!match && text(match[1]) === keyword;
    }

    async searchSeries(keyword, list, version) {
        if (!list.some((card) => this.matchesSeries(keyword, card.vod_name))) return {list};
        const groups = await this.net.map(list, async (card) => {
            if (!this.matchesSeries(keyword, card.vod_name)) return {list: [card]};
            try {
                return {list: await this.seriesCards(card, version)};
            } catch (error) {
                this.checkGeneration(version);
                return {list: [card], msg: '季別載入失敗：' + errorText(error)};
            }
        }, 2);
        const seen = new Set();
        const failed = groups.find((group) => group.msg);
        const result = {list: groups.flatMap((group) => group.list).filter((card) => !seen.has(card.vod_id) && seen.add(card.vod_id))};
        if (failed) result.msg = failed.msg;
        return result;
    }

    seriesCards(card, version) {
        const id = card.vod_id;
        return this.net.cached('hongguo:seasons:' + this.cacheOwner() + ':' + id, {ttl: WEB_TTL, stale: false}, async () => {
            this.checkGeneration(version);
            let cell = await seriesContent(this.net.req, this.device, id);
            this.checkGeneration(version);
            const videos = [], cursors = new Set();
            while (cell) {
                videos.push(...array(cell.video_data));
                if (cell.has_more !== true && cell.has_more !== 1) break;
                const cursor = {cell_id: text(cell.cell_id_str || cell.cell_id), offset: Number(cell.next_offset), session_id: text(cell.session_id)};
                const key = cursor.cell_id + ':' + cursor.offset;
                if (!cursor.cell_id || !Number.isFinite(cursor.offset) || cursor.offset <= 0 || cursors.has(key)) throw new Error('系列分頁游標未推進');
                cursors.add(key);
                cell = await seriesContent(this.net.req, this.device, id, cursor);
                this.checkGeneration(version);
            }
            const list = videos.filter((video) => video && Number(video.season_index) > 0 && Number(video.episode_cnt) > 0 && video.disable_play !== true)
                .sort((a, b) => Number(a.season_index) - Number(b.season_index)).map((video) => this.toCard({
                    series_id: video.series_id_str || video.series_id, series_name: video.title,
                    series_cover: video.cover, episode_cnt: video.episode_cnt
                })).filter(Boolean);
            return list.length ? list : [card];
        });
    }

    searchPage(keyword, cursor, version) {
        const key = 'hongguo:search:app:' + this.cacheOwner() + ':' + JSON.stringify([keyword, cursor]);
        return this.net.cached(key, {ttl: WEB_TTL, stale: false}, async () => {
            this.checkGeneration(version);
            const data = await this.withDevice((d) => searchTab(this.net.req, d, keyword, cursor, PAGE_SIZE));
            this.checkGeneration(version);
            const tab = array(data.search_tabs).find((item) => Number(item.tab_type) === 11);
            if (!tab) throw new Error('搜尋回應缺少短劇分頁');
            const offset = Number(tab.next_offset);
            const searchId = text(tab.search_id) || cursor.searchId;
            const more = (tab.has_more === true || tab.has_more === 1) && Number.isFinite(offset) && offset > cursor.offset && !!searchId;
            const next = more ? {offset, searchId, passback: text(tab.passback)} : null;
            return {list: this.feedCards(tab.data), next};
        });
    }

    toCard(item) {
        if (!object(item)) return null;
        const seriesId = text(item.series_id);
        if (!/^\d+$/.test(seriesId)) return null;
        return {
            vod_id: seriesId,
            vod_name: text(item.series_name || item.series_title) || '紅果短劇',
            vod_pic: this.picture(item.series_cover),
            vod_remarks: text(item.episode_right_text) || (item.episode_cnt ? '全' + item.episode_cnt + '集' : ''),
            style: {
                type: 'rect',
                ratio: 0.75
            }
        };
    }

    picture(url) {
        return withImageHeaders(text(url), {
            base: this.base + '/',
            referer: this.base + '/',
            ua: UA
        });
    }
}

// `_ROUTER_DATA = {...}` is followed by more script; scan the balanced object instead of trusting a delimiter.
function routerData(html) {
    const source = String(html || '');
    const match = /_ROUTER_DATA\s*=\s*/.exec(source);
    if (!match) throw new Error('頁面缺少資料');
    const start = source.indexOf('{', match.index + match[0].length);
    if (start < 0) throw new Error('頁面缺少資料');
    let depth = 0,
        inString = false,
        escaped = false;
    for (let i = start; i < source.length; i++) {
        const ch = source[i];
        if (inString) {
            if (escaped) escaped = false;
            else if (ch === '\\') escaped = true;
            else if (ch === '"') inString = false;
        } else if (ch === '"') inString = true;
        else if (ch === '{') depth++;
        else if (ch === '}' && --depth === 0) {
            const data = safeJson(source.slice(start, i + 1));
            if (!data) throw new Error('頁面資料解析失敗');
            return data;
        }
    }
    throw new Error('頁面資料不完整');
}
// Route names differ per page (category_$, detail_page, player_(series_id)/(vid)/page ...); pick the loader entry by field.
function findSection(data, field) {
    const loaders = data && object(data.loaderData) ? data.loaderData : {};
    for (const key of Object.keys(loaders)) {
        const value = loaders[key];
        if (object(value) && value[field] !== undefined && value[field] !== null) return value;
    }
    return null;
}

async function subtitleBlocks(html) {
    if (!html) return [];
    const {htmlQuery} = await import('catvod');
    return htmlQuery(html, {queries: {blocks: {
        selector: 'blk[p_idx][e_idx]',
        fields: {paragraph: {attribute: 'p_idx'}, element: {attribute: 'e_idx'}, content: {}}
    }}}).blocks;
}

async function audioVtt(points, html) {
    const index = new Map();
    const parts = [];
    let length = 0;
    for (const {paragraph, element, content} of await subtitleBlocks(html)) {
        if (typeof content !== 'string') continue;
        index.set(paragraph + ':' + element, {start: length, length: content.length});
        parts.push(content);
        length += content.length + 1;
    }
    const chapter = parts.join('\n');
    const cues = [];
    for (const point of points) {
        const from = Number(point?.start_time), to = Number(point?.end_time);
        if (!Number.isSafeInteger(from) || !Number.isSafeInteger(to) || from < 0 || to <= from) continue;
        const caption = text(point.text) || subtitleSlice(chapter, index, point.position_info_v2);
        if (!caption) continue;
        const line = caption.replace(/\s+/g, ' ').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        cues.push(vttTime(from) + ' --> ' + vttTime(to) + '\n' + line);
    }
    return cues.length ? 'WEBVTT\n\n' + cues.join('\n\n') + '\n' : '';
}

function subtitleSlice(chapter, index, position) {
    if (!position) return '';
    const first = index.get(position.start_container_index + ':' + position.start_element_index);
    const last = index.get(position.end_container_index + ':' + position.end_element_index);
    const start = position.start_element_offset, end = position.end_element_offset;
    if (!first || !last || !Number.isInteger(start) || !Number.isInteger(end)
            || start < 0 || start >= first.length || end < 0 || end > last.length) return '';
    return chapter.slice(first.start + start, last.start + Math.min(end + 1, last.length)).trim();
}

function vttTime(ms) {
    const pad = (value, digits = 2) => String(value).padStart(digits, '0');
    return pad(Math.floor(ms / 3600000)) + ':' + pad(Math.floor(ms / 60000) % 60) + ':'
        + pad(Math.floor(ms / 1000) % 60) + '.' + pad(ms % 1000, 3);
}

function playbackResult(stream, format) {
    const result = {parse: 0, jx: 0, url: stream.url, header: {'User-Agent': APP_UA}, format};
    if (stream.kid) {
        result.drm = {type: 'clearkey', key: clearKeyLicense(stream.kid, stream.key), forceKey: true};
    }
    return result;
}

function seriesIdOf(value) {
    const raw = String(value || '').trim();
    const match = /(?:^|[?&/])(?:series_id=)?(\d{6,})(?:$|[&/?#])/.exec(raw) || /^(\d{6,})$/.exec(raw);
    return match ? match[1] : '';
}

function cls(id, name) {
    return {
        type_id: id,
        type_name: name
    };
}

function safeJson(value) {
    try {
        return JSON.parse(value);
    } catch (error) {
        return null;
    }
}

function safeLabel(value) {
    return String(value == null ? '' : value).replace(/[$#]/g, ' ').trim() || '正片';
}

function object(value) {
    return !!value && typeof value === 'object' && !Array.isArray(value);
}

function array(value) {
    return Array.isArray(value) ? value : [];
}

function text(value) {
    return value == null ? '' : String(value).trim();
}

function pageNumber(value) {
    const n = parseInt(value, 10);
    return Number.isFinite(n) && n > 0 ? n : 1;
}

function normalizeBase(value) {
    const url = String(value || DEFAULT_BASE).replace(/\/+$/, '');
    return /^https?:\/\/[^/]+$/i.test(url) ? url : DEFAULT_BASE;
}

function errorText(error) {
    return String(error && error.message || error || '請求失敗').slice(0, 100);
}


